def arrow(x1, y1, x2, y2, w, c):
    a = math.atan2(y2 - y1, x2 - x1)
    bx, by = x2 - 3 * w * math.cos(a), y2 - 3 * w * math.sin(a)
    sx, sy = 2 * w * math.sin(a), 2 * w * math.cos(a)
    return [line(x1, y1, bx, by, w, c), P([(x2, y2), (round(bx - sx), round(by + sy)), (round(bx + sx), round(by - sy))], c)]


def face(cx, cy, r, c):
    e = max(2, r // 9)
    return [O(cx, cy, r, r, c, 14), O(cx - r // 3, cy - r // 6, e, e, IN), O(cx + r // 3, cy - r // 6, e, e, IN)]


def gavel(c):
    return [line(150, 70, 196, 116, 10, BR), line(122, 96, 160, 58, 24, c), R(150, 146, 80, 12, BR)]


